#!/bin/bash
# PATCH 104 - THE PRO CHART, TradingView style (on top of patch 103). In every share window, PRICE: PRO | TICK | 5 MIN + OI.
#   PRO = TradingView's Lightweight Charts (the library TradingView publishes, Apache 2.0, kept on this server):
#   · timeframes 1m (from the ticks) · 5m · 15m · 1h · 1D - 30 days of the stored 5-min history + today's live candles
#   · candles / Heikin-Ashi / bars / line · zoom (mouse wheel), pan (drag), the crosshair readout (O H L C V, % and the
#     indicators), ⟲ FIT, ⛶ full screen
#   · VWAP · EMA 9 · EMA 21 · SMA 50 · Bollinger (20, 2) · volume; below: RSI 14 · MACD (12, 26, 9) · OI added today
#   · LEVELS: the chain's R1-R3 / S1-S3 with their OI, yesterday's high / low / close - as lines on the price
#   · MARKS: every alert (ACT / MOVING / watch) and OI scenario on the bar it fired
#   · ─ LINE and ╱ TREND drawn by hand, kept per share (✕ removes them)
#   · the last candle moves every second with the live price; the whole chart redraws only when a new bar comes
#   dashserve.py (/hist, /lwc.js - exact anchors) · home.html · lwc.js. Installs p104test.py. Restarts gir-dash only.
D=/home/globalbot/intraday; TS=$(date +%m%d%H%M); W=/tmp/g104; mkdir -p $W
grep -q "NIFTY SHOCK|MARKET NEWS" $D/home.html || { echo "patch 103 is not installed yet - paste patch 103 first"; exit 1; }
grep -q "def hist(sym" $D/dashserve.py && { echo "patch 104 is already installed"; exit 1; }
F="dashserve.py home.html"
for f in $F; do cp $D/$f $D/$f.bak$TS; done
back() { for f in $F; do cp $D/$f.bak$TS $D/$f; done; rm -f $D/lwc.js $D/p104test.py; systemctl restart gir-dash; echo "ERROR - old files back, nothing changed"; exit 1; }
cat > $W/p104_patch.py <<'PY_PATCH'
#!/usr/bin/env python3
"""p104_patch.py - PATCH 104 (server side): the PRO chart's data. /hist?sym=&days= : a share's 5-min bars for the last N
trading days (the stored history, data/<SYM>.npz) + today's bars (charts.json, the engine's live candles), as one series.
/lwc.js : TradingView's Lightweight Charts library (Apache 2.0, kept next to the page), cached by the browser for a day.
Usage: python3 p104_patch.py /home/globalbot/intraday  (every anchor must match exactly once, else nothing is written)"""
import sys, os

D = sys.argv[1] if len(sys.argv) > 1 else "/home/globalbot/intraday"
EDITS = {}


def E(f, old, new):
    EDITS.setdefault(f, []).append((old, new))


E("dashserve.py", '''def live_ticks(sym):''', '''_HI = {}


def hist(sym, days=30):
    """patch 104: the PRO chart's bars - the stored 5-min history (last N days) + today's live candles, one series of
    {t: epoch of the bar's start, o, h, l, c, v}; cached 30 s per share"""
    sym = "".join(ch for ch in (sym or "").upper() if ch.isalnum() or ch in "&-")[:20]
    days = max(1, min(120, int(days or 30)))
    k = (sym, days)
    if k in _HI and time.time() - _HI[k][0] < 30:
        return _HI[k][1]
    rows = {}
    try:
        import core, numpy as np
        a = core.load_npz(sym)
        if a is not None and len(a["ts"]):
            ts = np.asarray(a["ts"], dtype=float)
            dd = (ts + 19800) // 86400
            keep = np.isin(dd, np.unique(dd)[-days:])
            for t_, o_, h_, l_, c_, v_ in zip(ts[keep], a["o"][keep], a["h"][keep], a["l"][keep], a["c"][keep], a["v"][keep]):
                if c_ == c_ and c_ > 0:
                    rows[int(t_)] = (float(o_), float(h_), float(l_), float(c_), float(v_ if v_ == v_ else 0))
    except Exception:
        pass
    pc = None
    try:
        ch = (json.load(open(os.path.join(BASE, "charts.json"))) or {}).get(sym) or {}
        st = live_obj() if "live_obj" in globals() else {}
        day = st.get("day") or dt.datetime.now(IST).strftime("%Y-%m-%d")
        t0 = int(dt.datetime.strptime(day + " 09:15", "%Y-%m-%d %H:%M").replace(tzinfo=IST).timestamp())
        pc = ch.get("pc")
        for i, c_ in enumerate(ch.get("c") or []):
            if c_ is None:
                continue
            o_, h_, l_ = ch["o"][i], ch["h"][i], ch["l"][i]
            rows[t0 + 300 * i] = (float(o_ if o_ is not None else c_), float(h_ if h_ is not None else c_), float(l_ if l_ is not None else c_), float(c_), float((ch.get("v") or [0] * (i + 1))[i] or 0))
    except Exception:
        pass
    ks = sorted(rows)
    v = {"s": sym, "pc": pc, "t": ks, "o": [round(rows[x][0], 2) for x in ks], "h": [round(rows[x][1], 2) for x in ks], "l": [round(rows[x][2], 2) for x in ks],
         "c": [round(rows[x][3], 2) for x in ks], "v": [int(rows[x][4]) for x in ks]}
    _HI[k] = (time.time(), v)
    if len(_HI) > 40:
        _HI.pop(next(iter(_HI)))
    return v


def live_ticks(sym):''')
E("dashserve.py", '''            if u.path == "/market":''', '''            if u.path == "/hist":                     # the PRO chart's bars (patch 104)
                q_ = parse_qs(u.query)
                return self.send(200, json.dumps(hist((q_.get("sym") or [""])[0], (q_.get("days") or ["30"])[0]), separators=(",", ":")), "application/json")
            if u.path == "/lwc.js":                   # TradingView Lightweight Charts (Apache 2.0) - the browser keeps it for a day (patch 104)
                body_ = open(os.path.join(BASE, "lwc.js"), "rb").read()
                self.send_response(200)
                if "gzip" in (self.headers.get("Accept-Encoding") or ""):
                    body_ = gzip.compress(body_, 6); self.send_header("Content-Encoding", "gzip")
                self.send_header("Content-Type", "application/javascript"); self.send_header("Cache-Control", "max-age=86400")
                self.send_header("Content-Length", str(len(body_))); self.end_headers(); self.wfile.write(body_)
                return
            if u.path == "/market":''')


def main():
    bad = 0
    texts = {}
    for f, edits in EDITS.items():
        p = os.path.join(D, f)
        if not os.path.exists(p):
            print("MISSING %s" % p); bad += 1; continue
        s = open(p, encoding="utf-8").read()
        for i, (old, new) in enumerate(edits, 1):
            n = s.count(old)
            if n != 1:
                print("ANCHOR %s #%d found %d times (need 1): %r" % (f, i, n, old[:90])); bad += 1
        texts[f] = s
    if bad:
        print("p104: %d anchors did not match - nothing written" % bad); sys.exit(1)
    for f, edits in EDITS.items():
        s = texts[f]
        for old, new in edits:
            s = s.replace(old, new, 1)
        open(os.path.join(D, f), "w", encoding="utf-8").write(s)
        print("p104: %-12s %2d edits" % (f, len(edits)))


if __name__ == "__main__":
    main()
