function vwapSeries(C,H,L,V){ let pv=0,vv=0; return C.map((c,i)=>{ if(c==null) return null; const tp=((H[i]??c)+(L[i]??c)+c)/3, v=V[i]||0; pv+=tp*v; vv+=v; return vv?pv/vv:c; }); }
