#!/usr/bin/env python3
"""p104test.py - the PRO chart: /hist joins the stored 5-min history and today's live candles (a scratch folder), /lwc.js is
served (gzip, kept a day by the browser), the page has the timeframes, chart types, indicators, studies, drawing, levels, marks"""
import os, sys, json, time, socket, threading, tempfile, datetime as dt
import numpy as np
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
B = os.path.dirname(os.path.abspath(__file__))
ok = True


def check(name, good):
    global ok
    print("  %s %s" % ("OK  " if good else "FAIL", name)); ok = ok and bool(good)


import dashserve, core
tmp = tempfile.mkdtemp(); os.makedirs(os.path.join(tmp, "data"))
core.DATA = os.path.join(tmp, "data")
IST = dt.timezone(dt.timedelta(hours=5, minutes=30))
ts = []
for k in range(40):                                          # 40 stored days of 5-min bars
    d0 = int(dt.datetime(2026, 9, 1, 9, 15, tzinfo=IST).timestamp()) + k * 86400
    ts += [d0 + 300 * i for i in range(75)]
ts = np.array(ts); c = 100 + np.arange(len(ts)) * 0.01
np.savez_compressed(os.path.join(core.DATA, "TESTSYM.npz"), ts=ts, o=c, h=c + 0.5, l=c - 0.5, c=c, v=np.full(len(ts), 1000))
real_base = dashserve.BASE
dashserve.BASE = tmp
json.dump({"TESTSYM": {"o": [200, 201], "h": [202, 203], "l": [199, 200], "c": [201, 202], "v": [5, 6], "pc": 199.5}}, open(os.path.join(tmp, "charts.json"), "w"))
dashserve.live_obj = lambda: {"day": "2026-11-10"}
h = dashserve.hist("TESTSYM", 30)
t_today = int(dt.datetime(2026, 11, 10, 9, 15, tzinfo=IST).timestamp())
check("30 stored days + today's 2 live candles = %d bars, in time order" % len(h["t"]), len(h["t"]) == 30 * 75 + 2 and h["t"] == sorted(h["t"]))
check("today's candles at 09:15 and 09:20 with yesterday's close %s" % h["pc"], h["t"][-2] == t_today and h["t"][-1] == t_today + 300 and h["c"][-1] == 202 and h["pc"] == 199.5)
check("a share with no history answers empty, not an error", dashserve.hist("NOSUCH", 30)["t"] == [])
open(os.path.join(tmp, "lwc.js"), "w").write(open(os.path.join(B, "lwc.js")).read())
srv = dashserve.ThreadingHTTPServer(("127.0.0.1", 0), dashserve.H); port = srv.server_address[1]
threading.Thread(target=srv.serve_forever, daemon=True).start()


def get(path, gz=False):
    s_ = socket.create_connection(("127.0.0.1", port), timeout=20)
    s_.sendall(("GET %s HTTP/1.0\r\nHost: x\r\n%s\r\n" % (path, "Accept-Encoding: gzip\r\n" if gz else "")).encode()); buf = b""
    while True:
        d_ = s_.recv(65536)
        if not d_:
            break
        buf += d_
    s_.close(); hd, _, body = buf.partition(b"\r\n\r\n"); return hd.decode("latin-1"), body


hd, body = get("/hist?k=%s&sym=TESTSYM&days=5" % dashserve.TOKEN)
j = json.loads(body) if b"200" in hd.split("\r\n")[0].encode() else {}
check("/hist answers with the token (5 days -> %d bars)" % len(j.get("t", [])), len(j.get("t", [])) == 5 * 75 + 2)
hd, body = get("/lwc.js?k=%s" % dashserve.TOKEN, gz=True)
check("/lwc.js: TradingView Lightweight Charts, gzip (%d bytes), kept by the browser a day" % len(body), " 200 " in hd.split("\r\n")[0] and "gzip" in hd and "max-age=86400" in hd)
hd, _ = get("/hist?k=wrong&sym=TESTSYM")
check("without the token -> 403", " 403 " in hd.split("\r\n")[0])
srv.shutdown(); dashserve.BASE = real_base
p = open(os.path.join(B, "home.html"), encoding="utf-8").read()
check("PRO chart: timeframes 1m 5m 15m 1h 1D · candles / Heikin-Ashi / bars / line", "function proBars" in p and '["D","1D"]' in p and '["ha","HEIKIN-ASHI"]' in p)
check("indicators VWAP · EMA 9 / 21 · SMA 50 · Bollinger · volume · RSI · MACD · OI", all(x in p for x in ('"VWAP"', '"EMA 9"', '"EMA 21"', '"SMA 50"', '"BOLL"', '"VOL"', '"RSI"', '"MACD"')))
check("the chain's R1-R3 / S1-S3 + yesterday's high / low / close as lines; alerts marked on their bar", "`R${i+1} ${x.k}" in p and '"PDH"' in p and "setMarkers" in p)
check("drawing: horizontal and trend lines kept per share; fit; full screen", "function proTool" in p and "gir_draw_" in p and "function proFull" in p)
check("the chart is kept across the live updates (only the last bar moves every second)", "PC.s.main.update(" in p)
check("patches 91-103 are still there", all(x in p for x in ("function shareListHTML", "function alertTier", "function drawMarket", "function applyQ", "function chkHTML", "function openWin", "NIFTY SHOCK|MARKET NEWS")))
print("\nP104 PRO CHART TEST %s" % ("PASSED" if ok else "FAILED"))
sys.exit(0 if ok else 1)
PY_TEST
